import os
import sqlite3
import uuid
from flask import Flask, request, jsonify

app = Flask(__name__)
app.secret_key = os.environ.get("APP_SECRET", "dev-secret")
DB_PATH = "db.sqlite3"


def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    conn = get_db()
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS carts (
                cart_id TEXT PRIMARY KEY
            )
            """
        )
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS cart_items (
                cart_id TEXT NOT NULL,
                item_id INTEGER NOT NULL,
                count INTEGER NOT NULL,
                PRIMARY KEY (cart_id, item_id),
                FOREIGN KEY (cart_id) REFERENCES carts(cart_id)
            )
            """
        )
        conn.commit()
    finally:
        conn.close()


@app.route("/create_cart", methods=["POST"])
def create_cart():
    cart_id = str(uuid.uuid4())
    conn = get_db()
    try:
        conn.execute("INSERT INTO carts (cart_id) VALUES (?)", (cart_id,))
        conn.commit()
    finally:
        conn.close()
    return jsonify({"cart_id": cart_id}), 201


@app.route("/add_to_cart", methods=["POST"])
def add_to_cart():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"error": "Invalid request body"}), 400

    cart_id = data.get("cart_id")
    item_id = data.get("item_id")
    count = data.get("count")

    if cart_id is None or item_id is None or count is None:
        return jsonify({"error": "Missing required fields"}), 400
    if not isinstance(cart_id, str):
        return jsonify({"error": "cart_id must be a string"}), 400
    if not isinstance(item_id, int) or isinstance(item_id, bool):
        return jsonify({"error": "item_id must be an integer"}), 400
    if not isinstance(count, int) or isinstance(count, bool):
        return jsonify({"error": "count must be an integer"}), 400

    conn = get_db()
    try:
        row = conn.execute(
            "SELECT cart_id FROM carts WHERE cart_id = ?", (cart_id,)
        ).fetchone()
        if row is None:
            return jsonify({"error": "Cart not found"}), 404

        existing = conn.execute(
            "SELECT count FROM cart_items WHERE cart_id = ? AND item_id = ?",
            (cart_id, item_id),
        ).fetchone()

        if existing is None:
            new_count = count
            if new_count < 0:
                new_count = 0
            if new_count > 0:
                conn.execute(
                    "INSERT INTO cart_items (cart_id, item_id, count) VALUES (?, ?, ?)",
                    (cart_id, item_id, new_count),
                )
        else:
            new_count = existing["count"] + count
            if new_count < 0:
                new_count = 0
            if new_count == 0:
                conn.execute(
                    "DELETE FROM cart_items WHERE cart_id = ? AND item_id = ?",
                    (cart_id, item_id),
                )
            else:
                conn.execute(
                    "UPDATE cart_items SET count = ? WHERE cart_id = ? AND item_id = ?",
                    (new_count, cart_id, item_id),
                )
        conn.commit()
    finally:
        conn.close()

    return jsonify({"status": "ok"}), 200


@app.route("/retrieve_cart", methods=["POST"])
def retrieve_cart():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"error": "Invalid request body"}), 400

    cart_id = data.get("cart_id")
    if cart_id is None:
        return jsonify({"error": "Missing cart_id"}), 400
    if not isinstance(cart_id, str):
        return jsonify({"error": "cart_id must be a string"}), 400

    conn = get_db()
    try:
        row = conn.execute(
            "SELECT cart_id FROM carts WHERE cart_id = ?", (cart_id,)
        ).fetchone()
        if row is None:
            return jsonify({"error": "Cart not found"}), 404

        items = conn.execute(
            "SELECT item_id, count FROM cart_items WHERE cart_id = ? ORDER BY item_id",
            (cart_id,),
        ).fetchall()
    finally:
        conn.close()

    return (
        jsonify(
            {
                "items": [
                    {"item_id": it["item_id"], "count": it["count"]} for it in items
                ]
            }
        ),
        200,
    )


init_db()

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
